import java.util.Scanner;

public class CF552C {
    static boolean possible(int w, int m) {
        if (m <= 0) {
            return true;
        }
        int r = m % w;
        if (r == 0) {
            return possible(w, m / w);
        } else if (r == 1) {
            return possible(w, (m - 1) / w);
        } else if (r == w - 1) {
            return possible(w, (m + 1) / w);
        } else {
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int w = in.nextInt();
        int m = in.nextInt();
        in.close();

        System.out.println(possible(w, m) ? "YES" : "NO");
    }
}
